class MedianFinder {
    private val lo = java.util.PriorityQueue<Int>(reverseOrder())  // smaller half, max-heap
    private val hi = java.util.PriorityQueue<Int>()                 // larger half, min-heap

    fun addNum(num: Int) {
        lo.add(num)
        hi.add(lo.poll())            // largest of lo moves to hi
        if (hi.size > lo.size) lo.add(hi.poll())  // keep lo >= hi, diff <= 1
    }

    fun findMedian(): Double =
        if (lo.size > hi.size) lo.peek().toDouble()
        else (lo.peek() + hi.peek()) / 2.0
}

