class Node(val value: Int) {
    var next: Node? = null
    var random: Node? = null
}

fun copyRandomList(head: Node?): Node? {
    val map = HashMap<Node, Node>()
    var cur = head
    while (cur != null) { map[cur] = Node(cur.value); cur = cur.next }
    cur = head
    while (cur != null) {
        val c = map.getValue(cur)
        c.next = cur.next?.let { map[it] }
        c.random = cur.random?.let { map[it] }
        cur = cur.next
    }
    return head?.let { map[it] }
}

