fun isValidBST(root: TreeNode?): Boolean {
    fun check(n: TreeNode?, lo: Long, hi: Long): Boolean {
        if (n == null) return true
        if (n.value <= lo || n.value >= hi) return false
        return check(n.left, lo, n.value.toLong()) &&
               check(n.right, n.value.toLong(), hi)
    }
    return check(root, Long.MIN_VALUE, Long.MAX_VALUE)
}

fun isValidBSTInOrder(root: TreeNode?): Boolean {
    var prev: Long? = null
    var ok = true
    fun walk(n: TreeNode?) {
        if (n == null || !ok) return
        walk(n.left)
        if (prev != null && n.value <= prev!!) { ok = false; return }
        prev = n.value.toLong()
        walk(n.right)
    }
    walk(root)
    return ok
}

