fun diameterOfBinaryTree(root: TreeNode?): Int {
    var best = 0
    fun height(n: TreeNode?): Int {
        if (n == null) return 0
        val l = height(n.left)
        val r = height(n.right)
        best = maxOf(best, l + r)
        return 1 + maxOf(l, r)
    }
    height(root)
    return best
}

