fun serialize(root: TreeNode?): String {
    val sb = StringBuilder()
    fun dfs(n: TreeNode?) {
        if (n == null) { sb.append("null,"); return }
        sb.append(n.value).append(',')
        dfs(n.left)
        dfs(n.right)
    }
    dfs(root)
    return sb.toString()
}

fun deserialize(data: String): TreeNode? {
    val q = ArrayDeque(data.split(',').filter { it.isNotEmpty() })
    fun build(): TreeNode? {
        val t = q.removeFirst()
        if (t == "null") return null
        val node = TreeNode(t.toInt())
        node.left = build()
        node.right = build()
        return node
    }
    return build()
}

